import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";
import "./Profile.css"; // custom CSS

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software Engineer",
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software Engineer"
          });
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem("token");
    if (!token) return;

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: {
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("✅ Profile updated successfully!");
      } else {
        setMessage("❌ Failed to update profile");
      }
    } catch (err) {
      console.error(err);
      setMessage("⚠️ Network error. Try again later.");
    }
  };

  if (loading) return (
    <div className="loading-container">
      <div className="loading-spinner"></div>
      <p>Loading profile...</p>
    </div>
  );

  return (
    <div className="profile-wrapper">
      {/* Left Side - Profile Form */}
      <div className="profile-content">
        <div className="profile-header">
          <h2 className="profile-title">My Profile</h2>
          <p className="profile-subtitle">Update your personal information</p>
        </div>

        <form onSubmit={handleSubmit} className="profile-form">
          <div className="form-group">
            <label className="form-label">Full Name</label>
            <input
              type="text"
              className="form-control-modern"
              name="fullName"
              value={profile.fullName}
              onChange={handleChange}
              placeholder="Enter your full name"
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Email Address</label>
            <input
              type="email"
              className="form-control-modern"
              name="email"
              value={profile.email}
              onChange={handleChange}
              placeholder="your@email.com"
              required
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Phone Number</label>
              <input
                type="tel"
                className="form-control-modern"
                name="phone"
                value={profile.phone}
                onChange={handleChange}
                placeholder="+1 (555) 123-4567"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Role</label>
              <input
                type="text"
                className="form-control-modern role-input"
                value={profile.role}
                readOnly
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Bio</label>
            <textarea
              className="form-control-modern bio-textarea"
              name="bio"
              rows="3"
              value={profile.bio}
              onChange={handleChange}
              placeholder="Tell us about yourself..."
            ></textarea>
          </div>

          <div className="form-actions">
            <button type="submit" className="btn-save">
              Save Changes
            </button>
            {message && <p className="message">{message}</p>}
          </div>
        </form>
      </div>

      {/* Right Side - Blue Theme Illustration */}
      <div className="profile-illustration">
        <div className="illustration-container">
          <div className="floating-shape shape-1"></div>
          <div className="floating-shape shape-2"></div>
          <div className="floating-shape shape-3"></div>
          
          <img
            src="https://images.unsplash.com/photo-1551434678-e076c223a692?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=800&q=80"
            alt="Modern tech workspace"
            className="main-illustration"
          />
          
          <div className="tech-badge badge-1">
            <span className="badge-icon">💻</span>
            <span className="badge-text">Development</span>
          </div>
          
          <div className="tech-badge badge-2">
            <span className="badge-icon">🚀</span>
            <span className="badge-text">Innovation</span>
          </div>
        </div>
      </div>
    </div>
  );
}
